    assessmentTools: { rubric: ['التسلسل', 'الدليل متعدد الأسباب', 'ضبط التفضيل والأفعال وحروفها', 'النقل المسؤول'], exitTicket: ['اكتب جملة بـ«بسبب» وأخرى بـ«أدّى… إلى…» واضبط آخر الكلمة بعدهما.'] },
